import React, { useState } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Button } from "react-bootstrap";

function History() {
  const [cameraId, setCameraId] = useState("CAM01");
  const [date, setDate] = useState("");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [data, setData] = useState({ labels: [], series: [] });

  const fetchHistory = async () => {
    if (!date) return alert("กรุณาเลือกวันที่");
    
    try {
      const response = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${date}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await response.json();
      setData(result);
    } catch (err) {
      console.error("Error fetching history:", err);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">ตรวจสอบประวัติรายวัน</Card.Title>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md="3">
                  <Form.Group>
                    <label>สถานี/สาย</label>
                    <Form.Control as="select" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                      <option value="CAM01">วิศวะ (CAM01)</option>
                      <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                      <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                      <option value="CAM04">PKY (CAM04)</option>
                    </Form.Control>
                  </Form.Group>
                </Col>
                <Col md="3">
                  <Form.Group>
                    <label>วันที่</label>
                    <Form.Control type="date" value={date} onChange={(e) => setDate(e.target.value)} />
                  </Form.Group>
                </Col>
                <Col md="2">
                  <Form.Group>
                    <label>เริ่มเวลา</label>
                    <Form.Control type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} />
                  </Form.Group>
                </Col>
                <Col md="2">
                  <Form.Group>
                    <label>ถึงเวลา</label>
                    <Form.Control type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} />
                  </Form.Group>
                </Col>
                <Col md="2" className="d-flex align-items-end">
                  <Button className="btn-fill w-100" variant="primary" onClick={fetchHistory}>ค้นหา</Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {data.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">สถิติจำนวนคน: {cameraId} ประจำวันที่ {date}</Card.Title>
              </Card.Header>
              <Card.Body>
                <ChartistGraph
                  data={data}
                  type="Line"
                  options={{
                    low: 0,
                    height: "300px",
                    showArea: true,
                    fullWidth: true,
                    axisX: { showGrid: false }
                  }}
                />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
